export type AppLanguage = 'nl' | 'en' | 'fr' | 'de' | 'es' | 'it' | 'bg' | 'hi' | 'ja' | 'pl' | 'id' | 'ar';

export const supportedAppLanguages: AppLanguage[] = ['nl', 'en', 'fr', 'de', 'es', 'it', 'bg', 'hi', 'ja', 'pl', 'id', 'ar'];

function normalizeAppLanguage(value: string | null | undefined): AppLanguage | null {
  const language = value?.trim().toLowerCase().slice(0, 2);
  return supportedAppLanguages.includes(language as AppLanguage) ? (language as AppLanguage) : null;
}

export function resolveAppLanguage(defaultLanguage: AppLanguage = 'nl'): AppLanguage {
  if (typeof window !== 'undefined') {
    const urlLanguage = new URLSearchParams(window.location.search).get('lang')
      ?? new URLSearchParams(window.location.search).get('language')
      ?? new URLSearchParams(window.location.search).get('locale');
    const resolvedUrlLanguage = normalizeAppLanguage(urlLanguage);
    if (resolvedUrlLanguage) {
      window.localStorage?.setItem('taze.language', resolvedUrlLanguage);
      return resolvedUrlLanguage;
    }

    const storedLanguage = normalizeAppLanguage(window.localStorage?.getItem('taze.language'));
    if (storedLanguage) return storedLanguage;
  }

  if (typeof navigator === 'undefined') return defaultLanguage;

  const browserLanguages = [...(navigator.languages ?? []), navigator.language]
    .filter(Boolean)
    .map((language) => normalizeAppLanguage(language));

  return browserLanguages.find((language): language is AppLanguage => Boolean(language)) ?? defaultLanguage;
}

